package dev.clearbrowser.core.data

/**
 * The canonical form of a URL as far as history and bookmarks are concerned,
 * or null when the URL is not something either of them should remember.
 *
 * ## Why only `http` and `https`
 *
 * A library entry is a page a person can come back to. `about:newtab` is the
 * browser's own empty page and `about:blank` is the engine's empty document,
 * `data:` URLs are self-contained documents that are
 * usually generated by a page, and `javascript:` is a command rather than a
 * place. Recording any of them puts unopenable rows in front of the user, which
 * makes the list look broken rather than useful.
 *
 * ## Why the fragment is dropped
 *
 * `#section` is a position inside a document, not a different document. Keeping
 * it would turn one page read top to bottom into a dozen entries that all look
 * identical in a list. The browser still navigates to the full URL; only the
 * stored identity is stripped.
 */
fun normalizeWebUrl(url: String): String? {
    val trimmed = url.trim()
    if (trimmed.isEmpty()) return null
    val scheme = trimmed.substringBefore(':').lowercase()
    if (scheme != "http" && scheme != "https") return null
    val withoutFragment = trimmed.substringBefore('#')
    if (withoutFragment.substringAfter("://").isBlank()) return null
    return withoutFragment
}
